SELECT (SELECT COUNT(*) FROM crypto_ai.replay_run_output) AS replay_run_output, (SELECT COUNT(*) FROM crypto_ai.replay_decision_trace) AS replay_decision_trace, (SELECT COUNT(*) FROM crypto_ai.replay_run_certificate) AS replay_run_certificate, (SELECT COUNT(*) FROM crypto_ai.trade_signal_test) AS trade_signal_test, (SELECT COUNT(*) FROM crypto_ai.wallet_position_test) AS wallet_position_test;